local URL="https://sirius.menu/gen2"local Rayfield=loadstring(game:HttpGet(URL))()local Window=Rayfield:CreateWindow({Name="空間建構修改選單",Subtitle="v18.0",Theme="Ocean",Configuration={Enabled=false}})local Main=Window:CreateTab({Name="⚙️ 主要"})local Items=Window:CreateTab({Name="⚔️ 道具"})local Hack=Window:CreateTab({Name="🔓 破解"})_G.GodModeActive=false _G.NoCooldownActive=false _G.InfItemsActive=false _G.RapidFireActive=false local spawnItem=""local scannedItems={}local scanLocs={game:GetService("ReplicatedStorage"),game:GetService("Lighting"),workspace}local function updateScannedItems()table.clear(scannedItems)for _,loc in ipairs(scanLocs)do pcall(function()for _,o in pairs(loc:GetDescendants())do if o:IsA("Tool")and o.Name~="必殺一體巨刃"and o.Name~="回血水"then if not table.find(scannedItems,o.Name)then table.insert(scannedItems,o.Name)end end end end)end if #scannedItems==0 then scannedItems={"ClassicSword","RocketLauncher","GravityGun"}end end updateScannedItems()local function obliterateCharacter(targetChar,localPlayer)if targetChar and targetChar:FindFirstChildOfClass("Humanoid")and targetChar.Name~=localPlayer.Name then targetChar:FindFirstChildOfClass("Humanoid").Health=0 task.wait()local joints={}for _,j in pairs(targetChar:GetDescendants())do if j:IsA("Motor3D")or j:IsA("Weld")or j:IsA("Snap")or j:IsA("Glue")or j:IsA("Motor")then table.insert(joints,j)end end for _,joint in pairs(joints)do pcall(function()joint:Destroy()end)end for _,v in pairs(targetChar:GetChildren())do if v:IsA("BasePart")then v.Velocity=Vector3.new(math.random(-60,60),math.random(30,80),math.random(-60,60))v.RotVelocity=Vector3.new(math.random(-25,25),math.random(-25,25),math.random(-25,25))end end end end Main:CreateToggle({Name="極速鎖血與原地復活無敵",CurrentValue=false,Callback=function(Value)_G.GodModeActive=Value local player=game.Players.LocalPlayer if not Value then return end task.spawn(function()while _G.GodModeActive do game:GetService("RunService").RenderStepped:Wait()local char=player.Character local hum=char and char:FindFirstChildOfClass("Humanoid")if hum and hum.Health<hum.MaxHealth and hum.Health>0 then hum.Health=hum.MaxHealth end end end)task.spawn(function()while _G.GodModeActive do local char=player.Character local hum=char and char:WaitForChild("Humanoid",5)local root=char and char:WaitForChild("HumanoidRootPart",5)if hum and root then local diedConn local lastLoc=root.CFrame diedConn=hum.Died:Connect(function()if _G.GodModeActive then Window:Notify({Title="系統提示",Content="正在原地強制復活...",Duration=2})local newChar=player.CharacterAdded:Wait()local nRoot=newChar:WaitForChild("HumanoidRootPart",5)local nHum=newChar:WaitForChild("Humanoid",5)if nRoot and nHum then task.wait(0.1)nRoot.CFrame=lastLoc nHum.Health=nHum.MaxHealth end end diedConn:Disconnect()end)end player.CharacterAdded:Wait()end end)Window:Notify({Title="無敵系統",Content="雙重鎖定防線已啟動",Duration=3})end})Main:CreateInput({Name="修改移動速度 (極速鎖定)",PlaceholderText="請輸入數字 (例如: 100)",RemoveTextAfterFocusLost=false,Callback=function(Text)local num=tonumber(Text)if num then local player=game.Players.LocalPlayer task.spawn(function()while task.wait()do local char=player.Character local hum=char and char:FindFirstChildOfClass("Humanoid")if hum then hum.WalkSpeed=num local root=char:FindFirstChild("HumanoidRootPart")if hum.MoveDirection.Magnitude>0 and root then root.Velocity=root.Velocity.Unitnum end end end end)Window:Notify({Title="成功",Content="速度已極速鎖定為: "..Text,Duration=2})end end})Main:CreateSlider({Name="角色體型大小調整",Range={0.2,5},Increment=0.1,CurrentValue=1,Callback=function(Value)local char=game.Players.LocalPlayer.Character if char and char:FindFirstChildOfClass("Humanoid")then pcall(function()char:ScaleTo(Value)end)end end})Items:CreateButton({Name="獲得必殺全維迴旋碎體神劍",Callback=function()local player=game.Players.LocalPlayer local bp=player:FindFirstChild("Backpack")or player:WaitForChild("Backpack",5)if not bp then return end local Sword=Instance.new("Tool")Sword.Name="必殺一體巨刃"Sword.RequiresHandle=true local Handle=Instance.new("Part",Sword)Handle.Name="Handle"Handle.Size=Vector3.new(0.5,7,0.7)Handle.BrickColor=BrickColor.new("Really black")Handle.Material=Enum.Material.Neon Handle.CanCollide=false Handle.Touched:Connect(function(hit)if Sword.Parent==player.Character then local tChar=hit.Parent obliterateCharacter(tChar,player)end end)local isBoomerangOut=false Sword.Activated:Connect(function()if isBoomerangOut then return end local char=player.Character local root=char and char:FindFirstChild("HumanoidRootPart")if not root then return end isBoomerangOut=true pcall(function()Handle.Transparency=1 end)local boom=Instance.new("Part")boom.Size=Vector3.new(0.5,7,0.7)boom.BrickColor=BrickColor.new("Really black")boom.Material=Enum.Material.Neon boom.CanCollide=false boom.CFrame=root.CFrameCFrame.new(0,0,-2)boom.Parent=workspace local bv=Instance.new("BodyVelocity",boom)bv.MaxForce=Vector3.new(math.huge,math.huge,math.huge)local randOffset=Vector3.new(math.random(-15,15),math.random(-5,15),math.random(-15,15))local targetPos=root.Position+(root.CFrame.LookVector65)+randOffset boom.Touched:Connect(function(hit)local tChar=hit.Parent obliterateCharacter(tChar,player)end)task.spawn(function()local rotX=math.random(15,45)local rotY=math.random(15,45)local rotZ=math.random(15,45)while boom.Parent do boom.CFrame=boom.CFrameCFrame.Angles(math.rad(rotX), math.rad(rotY), math.rad(rotZ))task.wait()end end)for i=1,35 do if not boom.Parent or not root then break end bv.Velocity=(targetPos-boom.Position).Unit60 task.wait(0.02)end for i=1,65 do if not boom.Parent or not root then break end bv.Velocity=(root.Position-boom.Position).Unit65 if (boom.Position-root.Position).Magnitude<5 then break end task.wait(0.02)end boom:Destroy()pcall(function()Handle.Transparency=0 end)isBoomerangOut=false end)Sword.Parent=bp pcall(function()player.Character.Humanoid:EquipTool(Sword)end)Window:Notify({Title="專用道具",Content="全維隨機雙向碎體巨刃已實體化!",Duration=2})end})Items:CreateButton({Name="獲得外掛回血水",Callback=function()local player=game.Players.LocalPlayer local bp=player:FindFirstChild("Backpack")or player:WaitForChild("Backpack",5)if not bp then return end local Potion=Instance.new("Tool")Potion.Name="回血水"Potion.RequiresHandle=true local Handle=Instance.new("Part",Potion)Handle.Name="Handle"Handle.Size=Vector3.new(1,1.2,1)Handle.BrickColor=BrickColor.new("Bright cyan")Handle.Material=Enum.Material.Glass Handle.CanCollide=false Potion.Activated:Connect(function()local char=player.Character local hum=char and char:FindFirstChildOfClass("Humanoid")if hum then hum.Health=hum.MaxHealth Window:Notify({Title="回血",Content="已滿血",Duration=1})end end)Potion.Parent=bp pcall(function()player.Character.Humanoid:EquipTool(Potion)end)Window:Notify({Title="道具",Content="回血水已放進背包並強制裝備!",Duration=2})end})Items:CreateButton({Name="複製當前手上道具 (雙重強制注入)",Callback=function()local player=game.Players.LocalPlayer local bp=player:FindFirstChild("Backpack")local tool=player.Character and player.Character:FindFirstChildOfClass("Tool")if tool and bp then local cloned=tool:Clone()cloned.Parent=bp task.wait(0.05)cloned.Parent=player.Character Window:Notify({Title="複製成功",Content="道具已注入手上",Duration=2})else Window:Notify({Title="失敗",Content="請先拿著道具",Duration=2})end end})Hack:CreateToggle({Name="高級全武器無冷卻鎖定 (高頻攔截)",CurrentValue=false,Callback=function(Value)_G.NoCooldownActive=Value if Value then local player=game.Players.LocalPlayer task.spawn(function()while _G.NoCooldownActive do game:GetService("RunService").Heartbeat:Wait()local char=player.Character if char then local tools={}for _,t in pairs(char:GetChildren())do if t:IsA("Tool")then table.insert(tools,t)end end if player:FindFirstChild("Backpack")then for _,t in pairs(player.Backpack:GetChildren())do if t:IsA("Tool")then table.insert(tools,t)end end end for _,t in pairs(tools)do pcall(function()if t:FindFirstChild("Cooldown")then t.Cooldown.Value=0 end if t:FindFirstChild("AttackCooldown")then t.AttackCooldown.Value=0 end if t:FindFirstChild("Rate")then t.Rate.Value=0 end if t:FindFirstChild("Delay")then t.Delay.Value=0 end if t:FindFirstChild("Enabled")then t.Enabled=true end for _,s in pairs(t:GetDescendants())do if s:IsA("NumberValue")or s:IsA("IntValue")or s:IsA("BoolValue")then local n=s.Name:lower()if n:match("cooldown")or n:match("delay")or n:match("rate")or n:match("wait")then s.Value=0 elseif n:match("ready")or n:match("canattack")then s.Value=true end end end end)end end end end)Window:Notify({Title="破解成功",Content="冷卻鎖定啟動",Duration=3})end end})Hack:CreateToggle({Name="全工具長按極速自動點擊連打",CurrentValue=false,Callback=function(Value)_G.RapidFireActive=Value if Value then local player=game.Players.LocalPlayer local uis=game:GetService("UserInputService")task.spawn(function()while _G.RapidFireActive do game:GetService("RunService").Heartbeat:Wait()local holding=uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)or uis:IsTouchFocused()if holding then local tool=player.Character and player.Character:FindFirstChildOfClass("Tool")if tool then pcall(function()tool.Enabled=true end)pcall(function()tool:Activate()end)end end end end)Window:Notify({Title="快速連打",Content="長按即可以高頻無冷卻連擊",Duration=3})end end})Hack:CreateToggle({Name="全道具彈藥/次數無限使用 (幀同步鎖定)",CurrentValue=false,Callback=function(Value)_G.InfItemsActive=Value if Value then local player=game.Players.LocalPlayer task.spawn(function()while _G.InfItemsActive do game:GetService("RunService").Heartbeat:Wait()local char=player.Character if char then local tools={}for _,t in pairs(char:GetChildren())do if t:IsA("Tool")then table.insert(tools,t)end end if player:FindFirstChild("Backpack")then for _,t in pairs(player.Backpack:GetChildren())do if t:IsA("Tool")then table.insert(tools,t)end end end for _,tool in pairs(tools)do pcall(function()for _,v in pairs(tool:GetDescendants())do if v:IsA("IntValue")or v:IsA("NumberValue")then local n=v.Name:lower()if n:match("ammo")or n:match("count")or n:match("amount")or n:match("uses")or n:match("durability")or n:match("clip")then v.Value=999 end end end end)end end end end)Window:Notify({Title="破解成功",Content="無限物品機制已啟動",Duration=2})end end})Hack:CreateToggle({Name="全場可見原地無敵復活",CurrentValue=false,Callback=function(Value)_G.GodModeActive=Value end})Hack:CreateDropdown({Name="選擇要生成的遊戲道具清單",Options=scannedItems,CurrentOption=scannedItems or "ClassicSword",MultipleOptions=false,Flag="ItemSpawnerDropdown",Callback=function(Option)spawnItem=Option end})Hack:CreateButton({Name="⚡ 100% 強制遠端事件認證獲取 (終極解決發放)",Callback=function()if spawnItem==""or spawnItem==nil then Window:Notify({Title="提示",Content="請先選取要發放的道具",Duration=2})return end local player=game.Players.LocalPlayer local bp=player:FindFirstChild("Backpack")or player:WaitForChild("Backpack",5)local char=player.Character if not bp or not char then return end local targetTool=nil for _,loc in ipairs(scanLocs)do pcall(function()for _,o in pairs(loc:GetDescendants())do if o:IsA("Tool")and o.Name==spawnItem then targetTool=o break end end end)if targetTool then break end end if targetTool then pcall(function()local remotes={}for _,v in pairs(game:GetDescendants())do if v:IsA("RemoteEvent")and(v.Name:lower():match("give")or v.Name:lower():match("item")or v.Name:lower():match("tool")or v.Name:match("buy")or v.Name:lower():match("get"))then table.insert(remotes,v)end end for _,remote in pairs(remotes)do pcall(function()remote:FireServer(spawnItem)end)pcall(function()remote:FireServer(targetTool)end)end local clone=targetTool:Clone()local part=clone:FindFirstChild("Handle")or clone:FindFirstChildOfClass("Part")or clone:FindFirstChildOfClass("MeshPart")clone.Parent=bp task.wait(0.02)if part and char:FindFirstChild("HumanoidRootPart")then local fakeClone=targetTool:Clone()fakeClone.Parent=workspace local fakePart=fakeClone:FindFirstChild("Handle")or fakeClone:FindFirstChildOfClass("Part")or fakeClone:FindFirstChildOfClass("MeshPart")if fakePart then fakePart.CanCollide=false fakePart.Anchored=true local connectTime=0 while fakeClone.Parent==workspace and connectTime<15 do if char and char:FindFirstChild("HumanoidRootPart")then fakePart.CFrame=char.HumanoidRootPart.CFrame end task.wait(0.01)connectTime=connectTime+1 end end pcall(function()fakeClone:Destroy()end)end task.wait(0.05)pcall(function()char.Humanoid:EquipTool(clone)end)end)Window:Notify({Title="生成成功",Content="已完美載入可用的: "..spawnItem,Duration=2})else pcall(function()local bIds={ClassicSword=121928763,RocketLauncher=13011314,GravityGun=20413122}local id=bIds[spawnItem]if id then local asset=game:GetObjects("rbxassetid://"..id)if asset then asset.Parent=bp task.wait(0.05)pcall(function()char.Humanoid:EquipTool(asset)end)Window:Notify({Title="網頁加載成功",Content="已從雲端載入基礎物品",Duration=2})end else Window:Notify({Title="失敗",Content="該環境不支援此物品發放",Duration=2})end end)end end})Hack:CreateButton({Name="更多",Callback=function()loadstring(game:HttpGet("https://sirius.menu/gen2"))()loadstring(game:HttpGet("https://raw.githubusercontent.com/as0968615051-netizen/go_hub/refs/heads/main/More/script-hub.lua"))()Window:Unload()end})
